WITH filtered AS (SELECT *, INITCAP(TRIM(name)) name_title FROM customers WHERE signup_date >= DATE '2023-08-25' AND segment IS NOT DISTINCT FROM 'Consumer'), not_flagged AS (SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM accounts ch WHERE ch.customer_id = s.id AND ch.opened_date >= s.signup_date)), with_last AS (SELECT s.*, latest.amount FROM not_flagged s LEFT JOIN LATERAL (SELECT c.amount FROM orders c WHERE c.customer_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE), not_flagged_customers AS (SELECT s.* FROM with_last s WHERE EXISTS (SELECT 1 FROM orders x WHERE x.customer_id = s.id AND x.order_date < '2025-11-01')), not_flagged_customers_2 AS (SELECT s.* FROM not_flagged_customers s WHERE EXISTS (SELECT 1 FROM orders ch WHERE ch.customer_id = s.id AND ch.order_date < s.signup_date)) SELECT country, ROUND(AVG(credit_limit), 2) AS avg_credit_limit, CORR(age, credit_limit) AS corr_age_credit_limit FROM not_flagged_customers_2 GROUP BY 1 HAVING corr_age_credit_limit >= 0
